import { SYNOPSIS_SCHEMA_VERSION, decodeByteFallback, dedupeSynopsisEpisodes, emptySynopsisSet, parseSynopsisSet, type ChapterSynopsisSet } from "../shared";
import { FileExistsError, FileNotFoundError, dirname, joinStorePath, type FileStore } from "./fileStore";
import { readTextFile, writeTextFilePreservingFormat, type TextFileContent, type WriteTextFailureReason } from "./textFile";
import { ledgerShapeProblem } from "./ledgerShapeGate";

/**
 * **各話あらすじの台帳**（`設定/chapter_synopses.json`。本体の `core/synopsisStore.ts` と同じ置き場・同じ形）。
 *
 * 作者のデータを書く道なので、本体と同じ守りを通す：
 * - **作者が書いたあらすじ（`autoGenerated: false`）は差し替えない**（差し込みは本体の `upsertSynopsis`。作者のメモも残る）
 * - **壊れた台帳は直さずに止める**（読めなければ投げる。書かない）
 * - **読んだあとで外で変わっていたら書かない**（同期や手で書き換わった。AI を呼ぶあいだに起こりうる）
 * - 書き換えるときは**元を退避してから**書く。書き戻しは `writeTextFilePreservingFormat`（ハッシュの照らし合わせ・退避・
 *   文字コードと改行の保持）を通す。無かった台帳は「無いときだけ作る」で作る（その間にできていたら上書きしない）
 * - 書く形は本体と同じ（`{ schemaVersion, episodes }` を2字下げ、末に改行）
 *
 * 本体と違うところ：読んだときに重複を片付けて書き直すこと（本体の `load` の片付けの保存）はしない。
 * 片付けは読んだ中身に当て、次に保存するときに一緒に書く
 */

export const CHAPTER_SYNOPSES_FILE = "chapter_synopses.json";

export interface LoadedSynopses {
  set: ChapterSynopsisSet;
  /** 読んだときの中身（無かったら null。書くときの照らし合わせに使う） */
  content: TextFileContent | null;
}

export type SaveSynopsesResult =
  | { ok: true; recoveryPath?: string }
  | { ok: false; reason: WriteTextFailureReason | "created_externally" | "write_failed" | "newer_shape"; detail?: string };

export function synopsesPath(settingsDir: string): string {
  return joinStorePath(settingsDir, CHAPTER_SYNOPSES_FILE);
}

export async function loadSynopses(store: FileStore, settingsDir: string): Promise<LoadedSynopses> {
  const path = synopsesPath(settingsDir);
  let content: TextFileContent;
  try {
    content = await readTextFile(store, path);
  } catch (error) {
    if (error instanceof FileNotFoundError) return { set: emptySynopsisSet(), content: null };
    throw error;
  }
  let parsed: ChapterSynopsisSet;
  try {
    // 本体と同じく、保存されてしまった文字化け（`<0xE5>…`）を読むたびに戻す
    parsed = parseSynopsisSet(JSON.parse(decodeByteFallback(content.text)));
  } catch (error) {
    throw new Error(`${CHAPTER_SYNOPSES_FILE} を読めませんでした：${error instanceof Error ? error.message : String(error)}`);
  }
  const deduped = dedupeSynopsisEpisodes(parsed.episodes);
  return { set: deduped.removed === 0 ? parsed : { ...parsed, episodes: deduped.episodes }, content };
}

export function synopsesText(set: ChapterSynopsisSet): string {
  return `${JSON.stringify({ schemaVersion: SYNOPSIS_SCHEMA_VERSION, episodes: set.episodes }, null, 2)}\n`;
}

export async function saveSynopses(store: FileStore, settingsDir: string, set: ChapterSynopsisSet, loaded: LoadedSynopses): Promise<SaveSynopsesResult> {
  const path = synopsesPath(settingsDir);
  const text = synopsesText(set);
  // モバイル版の知らない新しい形なら書かない（2026-11-21 作者の答え「台帳の形が変わったときだけ止める」）
  const newer = ledgerShapeProblem("各話あらすじ", loaded.content?.text, SYNOPSIS_SCHEMA_VERSION);
  if (newer) return { ok: false, reason: "newer_shape", detail: newer };
  if (loaded.content) {
    const written = await writeTextFilePreservingFormat(store, path, text, loaded.content, loaded.content.hash);
    if (!written.ok) return { ok: false, reason: written.reason, ...(written.detail !== undefined ? { detail: written.detail } : {}) };
    return { ok: true, ...(written.recoveryPath ? { recoveryPath: written.recoveryPath } : {}) };
  }
  try {
    await store.createDirectory(dirname(path));
    await store.writeFile(path, new TextEncoder().encode(text), { mode: "create" });
    return { ok: true };
  } catch (error) {
    if (error instanceof FileExistsError) return { ok: false, reason: "created_externally" };
    return { ok: false, reason: "write_failed", detail: error instanceof Error ? error.message : String(error) };
  }
}

/** 作者に出す一言（書けなかったとき） */
export function saveFailureText(result: Extract<SaveSynopsesResult, { ok: false }>): string {
  if (result.reason === "newer_shape" && result.detail) return result.detail;
  return result.reason === "modified_externally" || result.reason === "created_externally"
    ? `読んだあとで ${CHAPTER_SYNOPSES_FILE} が変わったので、書きませんでした（同期のあとでもう一度）`
    : `${CHAPTER_SYNOPSES_FILE} に書けませんでした`;
}
